  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 7 · Where I live</h2><p>Сегодня — где люди живут: город и деревня, дома и квартиры.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'flashcards', $blk${"title": "Повторяем слова урока. Нажми на карточку — услышишь слово и увидишь перевод", "cards": [{"text": "city", "translation": "большой город", "audio": "", "audio_tts": {"text": "city.", "voice": "en_GB-alba"}}, {"text": "town", "translation": "город, городок", "audio": "", "audio_tts": {"text": "town.", "voice": "en_GB-alba"}}, {"text": "village", "translation": "деревня", "audio": "", "audio_tts": {"text": "village.", "voice": "en_GB-alba"}}, {"text": "the country", "translation": "сельская местность", "audio": "", "audio_tts": {"text": "the country.", "voice": "en_GB-alba"}}, {"text": "island", "translation": "остров", "audio": "", "audio_tts": {"text": "island.", "voice": "en_GB-alba"}}, {"text": "a cottage", "translation": "домик в деревне", "audio": "", "audio_tts": {"text": "a cottage.", "voice": "en_GB-alba"}}, {"text": "a detached house", "translation": "отдельно стоящий дом", "audio": "", "audio_tts": {"text": "a detached house.", "voice": "en_GB-alba"}}, {"text": "a semi-detached house", "translation": "дом на две семьи", "audio": "", "audio_tts": {"text": "a semi-detached house.", "voice": "en_GB-alba"}}, {"text": "a terraced house", "translation": "дом в сплошном ряду домов", "audio": "", "audio_tts": {"text": "a terraced house.", "voice": "en_GB-alba"}}, {"text": "a block of flats", "translation": "многоквартирный дом", "audio": "", "audio_tts": {"text": "a block of flats.", "voice": "en_GB-alba"}}, {"text": "a flat", "translation": "квартира", "audio": "", "audio_tts": {"text": "a flat.", "voice": "en_GB-alba"}}, {"text": "an attic", "translation": "чердак, мансарда", "audio": "", "audio_tts": {"text": "an attic.", "voice": "en_GB-alba"}}, {"text": "a balcony", "translation": "балкон", "audio": "", "audio_tts": {"text": "a balcony.", "voice": "en_GB-alba"}}, {"text": "a lift", "translation": "лифт", "audio": "", "audio_tts": {"text": "a lift.", "voice": "en_GB-alba"}}, {"text": "stairs", "translation": "лестница", "audio": "", "audio_tts": {"text": "stairs.", "voice": "en_GB-alba"}}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай блог Лии про Великобританию и перетащи слова в пропуски", "mode": "drag", "text": "Most British people live on a big __island__. There is sea all around Britain.\nGlasgow is the biggest __city__ in Scotland, but it's not as big as London.\nThere are lots of farms in the __country__ in England. It's a very green place.\nBibury is a very old English __village__. It's a lovely place to visit.\nCriccieth is a small __town__ by the sea in North Wales. It's very pretty."}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини описание с типом дома", "pairs": [{"left": "This house looks like the houses on its left and right; their walls touch.", "right": "a terraced house"}, {"left": "It's a house; its walls don't touch other houses.", "right": "a detached house"}, {"left": "It's a big building with lots of homes in it.", "right": "a block of flats"}, {"left": "It's a small house in a village.", "right": "a cottage"}, {"left": "It's a house; one wall touches another house that looks the same.", "right": "a semi-detached house"}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай разговор ребят про их дома и выбери правильное слово", "questions": [{"q": "A: What ___ does Jeff live on?", "type": "single", "correct": [0], "options": [{"text": "floor"}, {"text": "attic"}]}, {"q": "B: The 5th, but there's a ___. We don't need to walk up there.", "type": "single", "correct": [0], "options": [{"text": "lift"}, {"text": "stairs"}]}, {"q": "A: Has his flat got a ___? B: Yes, so after school we can sit outside and look at the lake.", "type": "single", "correct": [1], "options": [{"text": "basement"}, {"text": "balcony"}]}, {"q": "C: Is this Kelly's house? D: Yes. Her bedroom is in the ___ at the top.", "type": "single", "correct": [0], "options": [{"text": "attic"}, {"text": "lift"}]}, {"q": "C: She has a lot of ___ to walk up and down!", "type": "single", "correct": [1], "options": [{"text": "balconies"}, {"text": "stairs"}]}, {"q": "D: And there is a gym in a room in the ___ under the house!", "type": "single", "correct": [0], "options": [{"text": "basement"}, {"text": "floor"}]}, {"q": "B: My mum's parents live ___ an island. I go there in the summer.", "type": "single", "correct": [0], "options": [{"text": "on"}, {"text": "in"}]}, {"q": "B: They live ___ a city.", "type": "single", "correct": [1], "options": [{"text": "on"}, {"text": "in"}]}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sort', $blk${"title": "Распредели слова по группам", "groups": [{"name": "🏙 где люди живут", "items": [{"text": "city"}, {"text": "town"}, {"text": "village"}, {"text": "the country"}, {"text": "island"}]}, {"name": "🏠 типы домов", "items": [{"text": "cottage"}, {"text": "detached house"}, {"text": "semi-detached house"}, {"text": "terraced house"}, {"text": "flat"}]}, {"name": "🪜 части дома", "items": [{"text": "3rd floor"}, {"text": "attic"}, {"text": "balcony"}, {"text": "lift"}, {"text": "stairs"}]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи, где ты живёшь: город это или деревня, какой у тебя дом или квартира, на каком этаже. Три-четыре предложения.</p>", "sample": "", "sample_tts": {"text": "My cousin lives in a small cottage in a quiet village.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_star.webp\" alt=\"\" style=\"height:200px\"></p><p>Готово! Теперь ты можешь рассказать про любой дом по-английски.</p>"}$blk$::jsonb, 7);
end $$;

