  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 7 · Present Continuous для будущего</h2><p>Сегодня — как по-английски говорят о планах, о которых уже договорились.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай предложение и реши: это происходит сейчас или это договорённость на будущее", "questions": [{"q": "I'm coming to your house right now.", "type": "single", "correct": [0], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "I'm coming to your house this evening.", "type": "single", "correct": [1], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "Diana and I are going to the shops now.", "type": "single", "correct": [0], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "Diana and I are going shopping at 6 p.m.", "type": "single", "correct": [1], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "Mum's driving us home after school.", "type": "single", "correct": [1], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "Mum's driving us home. We aren't on the bus.", "type": "single", "correct": [0], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "She's going to the cinema with her friends tonight.", "type": "single", "correct": [1], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}, {"q": "Look! Bob and Dan are going home. Bye!", "type": "single", "correct": [0], "options": [{"text": "сейчас, прямо в этот момент"}, {"text": "договорённость на будущее"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери правильную форму", "questions": [{"q": "Joe and I ___ making fish and chips tonight.", "type": "single", "correct": [0], "options": [{"text": "are"}, {"text": "is"}, {"text": "am"}]}, {"q": "Jeff and his brothers ___ going on the school trip tomorrow.", "type": "single", "correct": [1], "options": [{"text": "am not"}, {"text": "aren't"}, {"text": "isn't"}]}, {"q": "We aren't ___ house. We decided to stay in our old house.", "type": "single", "correct": [2], "options": [{"text": "move"}, {"text": "moved"}, {"text": "moving"}]}, {"q": "___ meeting you here at five?", "type": "single", "correct": [0], "options": [{"text": "Is she"}, {"text": "She isn't"}, {"text": "She's"}]}, {"q": "When ___ going on holiday?", "type": "single", "correct": [1], "options": [{"text": "you are"}, {"text": "are you"}, {"text": "you're"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "Next week Dad's", "right": "getting a new car."}, {"left": "My grandparents are visiting us", "right": "this weekend."}, {"left": "When are", "right": "you changing school?"}, {"left": "Are we playing tennis", "right": "today or tomorrow?"}, {"left": "Mum is picking", "right": "me up in a minute."}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Сегодня воскресенье. Посмотри на ежедневник Поппи и составь предложения", "items": [{"words": ["Tomorrow", "Poppy", "is", "going", "shopping", "with", "Mum."], "sentence": "Tomorrow Poppy is going shopping with Mum.", "prompt": "понедельник: go shopping with Mum"}, {"words": ["On", "Tuesday", "Poppy,", "Emma", "and", "George", "are", "meeting", "after", "school."], "sentence": "On Tuesday Poppy, Emma and George are meeting after school.", "prompt": "вторник: meet George and Emma after school"}, {"words": ["On", "Wednesday", "at", "4", "p.m.", "she", "is", "going", "to", "the", "chess", "club."], "sentence": "On Wednesday at 4 p.m. she is going to the chess club.", "prompt": "среда: go to the chess club at 4 p.m."}, {"words": ["On", "Thursday", "she", "is", "doing", "homework", "all", "evening."], "sentence": "On Thursday she is doing homework all evening.", "prompt": "четверг: do homework all evening"}, {"words": ["At", "the", "end", "of", "the", "week", "she", "is", "doing", "nothing."], "sentence": "At the end of the week she is doing nothing.", "prompt": "пятница: free! do nothing!"}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши пропущенное слово: ✔ — утвердительное предложение, ✘ — отрицательное", "mode": "type", "text": "what you / eat for dinner tonight\nWhat __are__ you __eating__ for dinner tonight?\n✘ burgers: We __aren't__ eating burgers.\n✔ pizza: We __are__ eating pizza.\nwhen they / meet Jane this afternoon\nWhen __are__ they __meeting__ Jane this afternoon?\n✘ six o'clock: They __aren't__ meeting her at six o'clock.\n✔ five o'clock: They __are__ meeting her at five o'clock."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши правдивые предложения о себе", "needs_review": true, "html": "<p>Используй Present Continuous для договорённостей. Там, где стоит ✔, предложение утвердительное, где ✘ — отрицательное.</p><ol><li>Tomorrow I … ✔</li><li>Next week my parents … ✘</li><li>Tonight my parents and I … ✔</li><li>At the weekend I … ✘</li></ol>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Планы на неделю теперь можно описать по-английски.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'cf15bae3-9e38-4b55-bf3d-a263b994126e' and title = 'Homework 3';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('cf15bae3-9e38-4b55-bf3d-a263b994126e', 'Homework 3', 2, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 2, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 7 · must, mustn't, can</h2><p>Сегодня — правила: что нужно делать, чего нельзя и что можно.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини предмет в доме с его описанием", "pairs": [{"left": "a bookcase", "right": "You keep your books on it."}, {"left": "a cupboard", "right": "You keep cups and plates in it, behind doors."}, {"left": "a drawer", "right": "You pull it out of a desk to get your things."}, {"left": "a mirror", "right": "You look at your face in it."}, {"left": "a sink", "right": "You wash the plates in it."}, {"left": "a tap", "right": "You turn it on and water comes out."}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши в школьные правила must или mustn't", "mode": "type", "text": "You __must__ arrive five minutes before the first lesson.\nYou __mustn't__ run in the classrooms.\nYou __must__ be quiet during a test.\nYou __mustn't__ give your homework to the teacher late.\nYou __mustn't__ fall asleep in class!\nYou __must__ put your hand up to ask a question!"}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери can, must или mustn't", "questions": [{"q": "You've finished your chores, so you ___ watch TV now.", "type": "single", "correct": [0], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "Turn off the tap. We ___ save water.", "type": "single", "correct": [1], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "___ I borrow a book from your bookcase, please?", "type": "single", "correct": [0], "options": [{"text": "Can"}, {"text": "Must"}, {"text": "Mustn't"}]}, {"q": "The sink is dirty. I ___ clean it.", "type": "single", "correct": [1], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "You ___ tidy your drawer. It is very messy.", "type": "single", "correct": [1], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "Be careful with that mirror. You ___ break it.", "type": "single", "correct": [2], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай указания доктора Кью и впиши по одному слову в каждый пропуск", "mode": "type", "text": "Dr Q: OK everyone, listen carefully. Today we __must__ get ready for Millie's surprise party. Here are my instructions. Pi, you __mustn't__ eat the nuts because they are for the party tonight. Rob, you __can__ choose the music - any songs you like. Remember, we __mustn't__ tell Millie about the party. It __must__ be a surprise.\nPi: Ha, ha, ha ...\nDr Q: What's the matter? Why are you laughing? You __mustn't__ laugh at me. It's rude!\nRob: Turn around. Millie is standing behind you ... and listening carefully too!"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши семейные правила про компьютер", "needs_review": true, "html": "<p>Напиши пять правил. Первые три — по подсказкам, ещё два придумай сам.</p><ol><li><b>must</b> — you / use the computer after ___ p.m.</li><li><b>mustn't</b> — you / chat online with your friends for ___ hour(s)</li><li><b>can</b> — parents / know your password</li><li>своё правило</li><li>ещё одно своё правило</li></ol>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_medal.webp\" alt=\"\" style=\"height:200px\"></p><p>Хорошо! Правила по-английски теперь не проблема.</p>"}$blk$::jsonb, 6);
end $$;

do $$
