  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай реплику и выбери подходящий ответ", "questions": [{"q": "A: Would you like to hang out tomorrow? B: ___", "type": "single", "correct": [1], "options": [{"text": "I'm sorry, you can't come."}, {"text": "Yes, I'd love to."}, {"text": "Thanks."}]}, {"q": "A: I'm going shopping. Can you come? B: ___", "type": "single", "correct": [2], "options": [{"text": "I mustn't come."}, {"text": "Sorry, I don't come."}, {"text": "I'm sorry, I can't come. I'm busy."}]}, {"q": "A: Do you want to go to the zoo on Saturday? B: ___", "type": "single", "correct": [0], "options": [{"text": "Sorry, maybe next time."}, {"text": "I love spiders."}, {"text": "Thank you."}]}, {"q": "B: I'd love to! Какой была реплика A?", "type": "single", "correct": [1], "options": [{"text": "Do you like going to the cinema?"}, {"text": "Do you want to come to the cinema?"}, {"text": "Do you often go to the cinema?"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Фрэн и Стэна и впиши пропущенные слова", "mode": "type", "text": "Fran: Hello, Stan. It's Fran. I've got two cinema tickets. Would you like to go?\nStan: I'd __love__ __to__. What time?\nFran: Eight o'clock.\nStan: Do __you__ __want__ __to__ go to the cinema in my car?\nFran: That __sounds__ __great__! Thank you. See you later!"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'sequence', $blk${"title": "Расставь реплики разговора по порядку", "items": [{"text": "Vicky: Hello, Micky. Are you free this afternoon?"}, {"text": "Vicky: I've got a new football. Would you like to play in the park?"}, {"text": "Micky: I'd love to. What time?"}, {"text": "Vicky: At five o'clock."}, {"text": "Micky: Can we meet at the park now?"}, {"text": "Vicky: Great! See you at five."}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши разговор-приглашение", "needs_review": true, "html": "<p>Вики звонит Мики: у неё новый мяч, и она зовёт его играть в футбол в парке в пять часов. Мики соглашается.</p><p>Напиши их разговор из шести-восьми реплик. Слова-помощники: <b>a new ball, great, football, o'clock, park</b>. Образцом возьми разговор Фрэн и Стэна из задания выше.</p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Позови друга куда-нибудь на выходных: скажи, куда и во сколько. Потом откажись от его приглашения и объясни почему. Четыре-пять предложений.</p>", "sample": "", "sample_tts": {"text": "Are you free on Saturday? Would you like to come to the swimming pool with me?", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_thumb.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Теперь ты знаешь, как приглашать и как отвечать на приглашение.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'cf15bae3-9e38-4b55-bf3d-a263b994126e' and title = 'Homework 5';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('cf15bae3-9e38-4b55-bf3d-a263b994126e', 'Homework 5', 4, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 4, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 7 · Reading</h2><p>Сегодня читаем блог Тревора о том, где живут его друзья.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери пропущенное слово", "questions": [{"q": "How can I find ___ what a word means?", "type": "single", "correct": [0], "options": [{"text": "out"}, {"text": "up"}, {"text": "for"}]}, {"q": "Let's check ___ the film times on the cinema website.", "type": "single", "correct": [1], "options": [{"text": "up"}, {"text": "out"}, {"text": "for"}]}, {"q": "We must clean ___ after the party. The house is messy.", "type": "single", "correct": [0], "options": [{"text": "up"}, {"text": "out"}, {"text": "for"}]}, {"q": "I can help you look ___ your car keys.", "type": "single", "correct": [0], "options": [{"text": "for"}, {"text": "up"}, {"text": "out"}]}, {"q": "I usually wake ___ at seven o'clock in the morning.", "type": "single", "correct": [0], "options": [{"text": "up"}, {"text": "out"}, {"text": "for"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<h3>Green and clean neighbourhood blog <span style=\"color:#888\">by Trevor</span></h3><p>My friends live in different parts of the UK. Check out their posts on my neighbourhood blog.</p><p><b>Hugh</b><br>I live in a small cottage in a quiet village. There are lots of flowers in our garden. When we peel vegetables and fruit, we keep the skins. After some time, the skins go brown and we can use them in the garden! They are good for the plants - they make them grow healthier and stronger.</p><p><b>Carly</b><br>I live on the 4th floor of a block of flats. When we moved here, there was only a dirty car park next to the building. One day the families here decided to grow grass and trees behind the building. Now we also regularly clean up the car park to keep the neighbourhood nice and green.</p><p><b>Zach</b><br>I live in a city. I'd like to live in a big detached house like Trevor, but they are too expensive! My street has terraced houses and our houses are all different colours! Last year everyone in my street decided to paint their houses because we wanted to live in a nicer and cleaner neighbourhood. There is a white house, a ‘coffee cream’ house, a red and white house and my house!</p>"}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Прочитай блог и соедини человека с его домом", "pairs": [{"left": "Hugh", "right": "a small cottage in a quiet village"}, {"left": "Carly", "right": "a flat on the 4th floor of a block of flats"}, {"left": "Zach", "right": "a terraced house in a city street"}, {"left": "Trevor", "right": "a big detached house"}], "material": "<h3>Green and clean neighbourhood blog <span style=\"color:#888\">by Trevor</span></h3><p>My friends live in different parts of the UK. Check out their posts on my neighbourhood blog.</p><p><b>Hugh</b><br>I live in a small cottage in a quiet village. There are lots of flowers in our garden. When we peel vegetables and fruit, we keep the skins. After some time, the skins go brown and we can use them in the garden! They are good for the plants - they make them grow healthier and stronger.</p><p><b>Carly</b><br>I live on the 4th floor of a block of flats. When we moved here, there was only a dirty car park next to the building. One day the families here decided to grow grass and trees behind the building. Now we also regularly clean up the car park to keep the neighbourhood nice and green.</p><p><b>Zach</b><br>I live in a city. I'd like to live in a big detached house like Trevor, but they are too expensive! My street has terraced houses and our houses are all different colours! Last year everyone in my street decided to paint their houses because we wanted to live in a nicer and cleaner neighbourhood. There is a white house, a ‘coffee cream’ house, a red and white house and my house!</p>"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай блог ещё раз и выбери правильный ответ", "questions": [{"q": "Who lives in a village?", "type": "single", "correct": [0], "options": [{"text": "Hugh"}, {"text": "Carly"}, {"text": "Zach"}]}, {"q": "Who would like to live in a detached house?", "type": "single", "correct": [2], "options": [{"text": "Hugh"}, {"text": "Carly"}, {"text": "Zach"}]}, {"q": "What was next to Carly's block of flats when she moved there?", "type": "single", "correct": [0], "options": [{"text": "a dirty car park"}, {"text": "a green park"}, {"text": "a small school"}]}, {"q": "Who lives in a street with different colour houses?", "type": "single", "correct": [2], "options": [{"text": "Hugh"}, {"text": "Carly"}, {"text": "Zach"}]}, {"q": "What does Hugh use in his garden to make the plants healthier?", "type": "single", "correct": [0], "options": [{"text": "the skins of vegetables and fruit"}, {"text": "water from the river"}, {"text": "flowers from the shop"}]}, {"q": "Why did the people in Carly's building grow grass and trees?", "type": "single", "correct": [0], "options": [{"text": "to keep the neighbourhood nice and green"}, {"text": "to sell the flowers"}, {"text": "because the car park was too small"}]}], "material": "<h3>Green and clean neighbourhood blog <span style=\"color:#888\">by Trevor</span></h3><p>My friends live in different parts of the UK. Check out their posts on my neighbourhood blog.</p><p><b>Hugh</b><br>I live in a small cottage in a quiet village. There are lots of flowers in our garden. When we peel vegetables and fruit, we keep the skins. After some time, the skins go brown and we can use them in the garden! They are good for the plants - they make them grow healthier and stronger.</p><p><b>Carly</b><br>I live on the 4th floor of a block of flats. When we moved here, there was only a dirty car park next to the building. One day the families here decided to grow grass and trees behind the building. Now we also regularly clean up the car park to keep the neighbourhood nice and green.</p><p><b>Zach</b><br>I live in a city. I'd like to live in a big detached house like Trevor, but they are too expensive! My street has terraced houses and our houses are all different colours! Last year everyone in my street decided to paint their houses because we wanted to live in a nicer and cleaner neighbourhood. There is a white house, a ‘coffee cream’ house, a red and white house and my house!</p>"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Ответь на вопросы о себе", "needs_review": true, "html": "<p>Ответь письменно, по два-три предложения на каждый вопрос.</p><ol><li>What type of house do you live in?</li><li>Is your neighbourhood nice? Why?</li><li>What can you do to make your neighbourhood nicer?</li></ol>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_popper.webp\" alt=\"\" style=\"height:200px\"></p><p>Здорово! Блог прочитан, про свой район рассказано.</p>"}$blk$::jsonb, 6);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'cf15bae3-9e38-4b55-bf3d-a263b994126e' and title = 'Homework 6';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('cf15bae3-9e38-4b55-bf3d-a263b994126e', 'Homework 6', 5, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 5, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 7 · Listening and Writing</h2><p>Сегодня слушаем рассказ Чарли про его дом и пишем приглашение.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини часть дома с её описанием", "pairs": [{"left": "a balcony", "right": "You can stand outside here and look at the garden."}, {"left": "the basement", "right": "This room is under the house, below the ground."}, {"left": "the ground floor", "right": "This floor is at the same level as the garden."}, {"left": "the 1st floor", "right": "In Britain this is the floor above the ground floor."}, {"left": "the 2nd floor", "right": "This floor is above the 1st floor."}, {"left": "the stairs", "right": "You walk up and down these when there is no lift."}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "LISTENING 🎧 Послушай рассказ Чарли и выбери, кто где живёт", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A18.mp3", "skill": "listening", "questions": [{"q": "Charlie's uncle lives ...", "type": "single", "correct": [0], "options": [{"text": "in a small flat"}, {"text": "on the top floor"}, {"text": "next door to each other"}, {"text": "on the ground floor"}]}, {"q": "Charlie and Amin live ...", "type": "single", "correct": [2], "options": [{"text": "in a small flat"}, {"text": "on the top floor"}, {"text": "next door to each other"}, {"text": "on the ground floor"}]}, {"q": "Amin's grandparents live ...", "type": "single", "correct": [3], "options": [{"text": "in a small flat"}, {"text": "on the top floor"}, {"text": "next door to each other"}, {"text": "on the ground floor"}]}, {"q": "Mary lives ...", "type": "single", "correct": [1], "options": [{"text": "in a small flat"}, {"text": "on the top floor"}, {"text": "next door to each other"}, {"text": "on the ground floor"}]}, {"q": "Where does the uncle keep his bike?", "type": "single", "correct": [1], "options": [{"text": "on his balcony"}, {"text": "in the basement"}, {"text": "in the garden"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "LISTENING 🎧 Послушай рассказ ещё раз и впиши по одному слову", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A18.mp3", "mode": "type", "text": "Charlie's uncle's flat is small but __cool__.\nThe __lift__ doesn't go down to the basement.\nAmin is Charlie's best __friend__.\nThe __doors__ of Charlie and Amin's flats are always open.\nAmin's grandma makes them __pancakes__ when they clean up for her.\nThey're having a Mother's Day party on __Sunday__."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'exact_input', $blk${"title": "В приглашении Салли восемь ошибок. Прочитай строку и напиши слово правильно", "items": [{"prompt": "Woud you like to have lunch at my house with my family?", "accept": ["Would", "would"]}, {"prompt": "We having a picnic in the garden.", "accept": ["We're", "We are", "we're"]}, {"prompt": "Its a great way to meet old and new neighbours.", "accept": ["It's", "it's"]}, {"prompt": "Lots of my friends from the neihbourhood are coming.", "accept": ["neighbourhood", "Neighbourhood"]}, {"prompt": "Can you come at about eleven oclock?", "accept": ["o'clock", "O'clock"]}, {"prompt": "Dad says we can play table tenis in the garage.", "accept": ["tennis", "Tennis"]}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши другу письмо-приглашение", "needs_review": true, "html": "<p>Сначала выбери, о чём будешь писать:</p><ul><li><b>Day:</b> Friday / Saturday / Sunday</li><li><b>Activity 1:</b> the cinema / shopping / football</li><li><b>Time:</b> eleven o'clock / 2 p.m. / five o'clock</li><li><b>Activity 2:</b> a picnic / computer games / burgers</li><li><b>Useful verbs:</b> do / get / go / hang out / like / make / meet / play / want</li></ul><p>Теперь напиши письмо на 60–80 слов. Начни так: <i>Hi Marek, What are you doing next ...?</i> Перечитай письмо и проверь орфографию и знаки препинания.</p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_certificate.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! И рассказ послушали, и приглашение написали.</p>"}$blk$::jsonb, 6);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'cf15bae3-9e38-4b55-bf3d-a263b994126e' and title = 'Homework 7';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('cf15bae3-9e38-4b55-bf3d-a263b994126e', 'Homework 7', 6, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 6, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 7 · Check yourself!</h2><p>Повторяем весь юнит перед тестом.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай рассказ про Сандру и выбери правильное слово", "mode": "choice", "text": "Sandra lives in a __cottage__. It's in a pretty __village__ in the country. Every day she wakes up and she looks in the __mirror__ in the bathroom and she brushes her teeth. Then she goes to the kitchen and she gets a mug from the __cupboard__, so she can make tea. She likes sitting on the __stairs__ to drink her morning tea because her cat sits there. She is a tidy girl, so she always __cleans up__ after her tea.", "choices": [["detached house"], ["city"], ["tap"], ["sink"], ["basement"], ["finds out"]]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "David lives in a block", "right": "of flats."}, {"left": "My flat is on the ground", "right": "floor."}, {"left": "Grandpa lives in a terraced", "right": "house."}, {"left": "Life in the city is", "right": "often noisy."}, {"left": "I'd like to live on", "right": "an island."}, {"left": "You can use the lift to", "right": "go to the 2nd floor."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши глагол в Present Continuous — речь о договорённостях на будущее", "mode": "type", "text": "We __are moving__ (move) to a new house next week.\nDave __is meeting__ (meet) us at seven o'clock at my house.\nHurry up! We __are leaving__ (leave) in five minutes!\n__What is Fred doing__ (what / Fred do) tomorrow?\n__Are you watching__ (you / watch) anything good on TV tonight?\nMandy __isn't running__ (not run) in the race on Saturday. She's sick."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Выбери can, must или mustn't", "questions": [{"q": "We ___ hurry up. The train is leaving in a moment.", "type": "single", "correct": [1], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "You ___ watch TV after you do your homework.", "type": "single", "correct": [0], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "Stop! You ___ cross the road here. It's not safe.", "type": "single", "correct": [2], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "Your bedroom is messy. You ___ tidy it this weekend.", "type": "single", "correct": [1], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "It's raining. We ___ take an umbrella.", "type": "single", "correct": [1], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}, {"q": "We ___ play football in the garden. Dad says it's OK.", "type": "single", "correct": [0], "options": [{"text": "can"}, {"text": "must"}, {"text": "mustn't"}]}]}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай разговоры и выбери правильный вариант", "questions": [{"q": "A: ___ like to come to my house on Sunday?", "type": "single", "correct": [0], "options": [{"text": "Would you"}, {"text": "You would"}]}, {"q": "B: ___ to. Can I come with Jiggs, my dog?", "type": "single", "correct": [1], "options": [{"text": "I love"}, {"text": "I'd love"}]}, {"q": "A: ___ you want to see the match with me this afternoon?", "type": "single", "correct": [0], "options": [{"text": "Do"}, {"text": "Would"}]}, {"q": "B: ___ sorry I can't see it. I'm busy this afternoon.", "type": "single", "correct": [1], "options": [{"text": "I"}, {"text": "I'm"}]}, {"q": "A: Are you free tomorrow? Would you ___ to go to the country?", "type": "single", "correct": [0], "options": [{"text": "like"}, {"text": "want"}]}, {"q": "B: Sorry. Maybe ___ time.", "type": "single", "correct": [0], "options": [{"text": "next"}, {"text": "this"}]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Позови друга в гости на выходных: скажи, где ты живёшь, какой у тебя дом и что вы будете делать. Четыре-пять предложений.</p>", "sample": "", "sample_tts": {"text": "I live in a flat on the third floor of a block of flats.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Юнит пройден! Можно браться за тест.</p>"}$blk$::jsonb, 7);
end $$;
